$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Web.Extensions
$serializer = New-Object System.Web.Script.Serialization.JavaScriptSerializer
$serializer.MaxJsonLength = 2147483647

$bytes = [System.IO.File]::ReadAllBytes("$env:TEMP\opencode\opencode_copy.db")
$text = [System.Text.Encoding]::UTF8.GetString($bytes)

$sid = 'ses_f4e508695ffeguNWxcKifyQgHS'

function ParseObjectsAround($haystack, $needle) {
    $results = @()
    $idx = 0
    while (($idx = $haystack.IndexOf($needle, $idx)) -ge 0) {
        $objStart = $idx
        while ($objStart -gt 0 -and $haystack[$objStart] -ne '{') { $objStart-- }
        if ($haystack[$objStart] -ne '{') { $idx += $needle.Length; continue }
        $depth = 0; $inStr = $false; $esc = $false; $end = $objStart
        for ($i = $objStart; $i -lt $haystack.Length; $i++) {
            $c = $haystack[$i]
            if ($inStr) {
                if ($esc) { $esc = $false }
                elseif ($c -eq '\') { $esc = $true }
                elseif ($c -eq '"') { $inStr = $false }
            } else {
                if ($c -eq '"') { $inStr = $true }
                elseif ($c -eq '{') { $depth++ }
                elseif ($c -eq '}') { $depth--; if ($depth -eq 0) { $end = $i; break } }
            }
        }
        try {
            $json = $haystack.Substring($objStart, $end - $objStart + 1)
            $obj = $serializer.DeserializeObject($json)
            if ($obj -is [System.Collections.Generic.Dictionary[String,Object]]) {
                $results += , $obj
            }
        } catch {}
        $idx = $end + $needle.Length
    }
    return $results
}

# Extract message roles
$roleById = @{}
$msgNeedle = '"sessionID":"' + $sid + '","role":"'
$msgIdx = 0
while (($msgIdx = $text.IndexOf($msgNeedle, $msgIdx)) -ge 0) {
    $start = $msgIdx
    while ($start -gt 0 -and $text[$start] -ne '{') { $start-- }
    if ($text[$start] -eq '{') {
        $inStr=$false;$esc=$false;$depth=0;$end=$start
        for ($i=$start; $i -lt $text.Length; $i++) {
            $c=$text[$i]
            if ($inStr) { if ($esc){$esc=$false} elseif ($c -eq '\'){$esc=$true} elseif ($c -eq '"'){$inStr=$false} }
            else { if ($c -eq '"'){$inStr=$true} elseif ($c -eq '{'){$depth++} elseif ($c -eq '}'){$depth--; if($depth -eq 0){$end=$i;break}} }
        }
        try {
            $json = $text.Substring($start, $end-$start+1)
            $obj = $serializer.DeserializeObject($json)
            if ($obj -is [System.Collections.Generic.Dictionary[String,Object]]) {
                $id = $obj['id']; $role = $obj['role']
                if ($id -and $role) { $roleById[$id] = $role }
            }
        } catch {}
    }
    $msgIdx = $end + $msgNeedle.Length
}

# Extract parts
$partNeedle = '"id":"prt_'
$rows = @()
$pidx = 0
while (($pidx = $text.IndexOf($partNeedle, $pidx)) -ge 0) {
    $start = $pidx
    while ($start -gt 0 -and $text[$start] -ne '{') { $start-- }
    if ($text[$start] -eq '{') {
        $inStr=$false;$esc=$false;$depth=0;$end=$start
        for ($i=$start; $i -lt $text.Length; $i++) {
            $c=$text[$i]
            if ($inStr) { if ($esc){$esc=$false} elseif ($c -eq '\'){$esc=$true} elseif ($c -eq '"'){$inStr=$false} }
            else { if ($c -eq '"'){$inStr=$true} elseif ($c -eq '{'){$depth++} elseif ($c -eq '}'){$depth--; if($depth -eq 0){$end=$i;break}} }
        }
        $json = $text.Substring($start, $end-$start+1)
        if ($json -match ('"sessionID":"' + [regex]::Escape($sid) + '"')) {
            try {
                $obj = $serializer.DeserializeObject($json)
                if ($obj -is [System.Collections.Generic.Dictionary[String,Object]]) {
                    $type = $obj['type']
                    if ($type -eq 'text' -or $type -eq 'reasoning' -or $type -eq 'summary') {
                        $tid = $obj['id']; $mid = $obj['messageID']; $txt = $obj['text']
                        $t = 0; if ($obj.ContainsKey('time')) { $t = [long]$obj['time'] }
                        $rows += , [pscustomobject]@{ Time=$t; Msg=$mid; Type=$type; Text=$txt; Role=($roleById[$mid]) }
                    }
                }
            } catch {}
        }
    }
    $pidx = $end + $partNeedle.Length
}

$rows = $rows | Sort-Object Time
$sb = New-Object System.Text.StringBuilder
foreach ($r in $rows) {
    $d = if ($r.Time) { ([DateTimeOffset]::FromUnixTimeMilliseconds($r.Time).ToLocalTime().ToString('yyyy-MM-dd HH:mm:ss')) } else { '????-' }
    $who = if ($r.Role) { $r.Role } else { '?' }
    [void]$sb.AppendLine("[$d] msg=$($r.Msg) role=$who type=$($r.Type)")
    $clean = '' + $r.Text
    [void]$sb.AppendLine($clean)
    [void]$sb.AppendLine('========================================')
}
$out = $sb.ToString()
[System.IO.File]::WriteAllText("$env:TEMP\opencode\arsheef_full_session.txt", $out, (New-Object System.Text.UTF8Encoding($false)))
"messages with roles: $($roleById.Count)"
"parts (text/reasoning/summary): $($rows.Count)"
"bytes written: $([System.IO.File]::ReadAllBytes("$env:TEMP\opencode\arsheef_full_session.txt").Length)"

$ErrorActionPreference = 'Stop'
$bytes = [System.IO.File]::ReadAllBytes("$env:TEMP\opencode\opencode_copy.db")
$text = [System.Text.Encoding]::UTF8.GetString($bytes)
$sid = 'ses_f4e508695ffeguNWxcKifyQgHS'
$sidNeedle = '"sessionID":"' + $sid + '"'

# ---- roles ----
$roleById = @{}
$midNeedle = '"sessionID":"' + $sid + '","role":"'
$i = 0
while (($i = $text.IndexOf($midNeedle, $i)) -ge 0) {
    $seg = $text.Substring($i - 200, [Math]::Min(400, $text.Length - ($i - 200)))
    $idm = [regex]::Match($seg, '"id":"(msg_[^"]*)"')
    $rl  = [regex]::Match($seg, '"role":"([^"]*)"')
    if ($idm.Success -and $rl.Success -and -not $roleById.ContainsKey($idm.Groups[1].Value)) {
        $roleById[$idm.Groups[1].Value] = $rl.Groups[1].Value
    }
    $i += $midNeedle.Length
}

# ---- parts ----
function Get-Parts($text, $sidNeedle, $typeNeedle, $collect) {
    $i = 0
    while (($i = $text.IndexOf($typeNeedle, $i)) -ge 0) {
        $start = $i
        while ($start -gt 0 -and $text[$start] -ne '{') { $start-- }
        $objStart = $start
        # bound check: ensure session id is within object before marker
        $head = $text.Substring($objStart, $i - $objStart)
        if ($head.IndexOf($sidNeedle) -ge 0 -and $text[$objStart] -eq '{') {
            # get messageID backwards
            $midm = [regex]::Match($head, '"messageID":"(msg_[^"]*)"')
            $mid = if ($midm.Success) { $midm.Groups[1].Value } else { '?' }
            $p = $i + $typeNeedle.Length
            $sb = New-Object System.Text.StringBuilder
            $esc = $false
            for ($k = $p; $k -lt $text.Length; $k++) {
                $c = $text[$k]
                if ($c -eq '\') { $esc = -not $esc } else { if (-not $esc -and $c -eq '"') { break } ; $esc = $false }
                if ($c -ne '"' -or $esc) { [void]$sb.Append($c) }
            }
            $raw = $sb.ToString()
            $after = $text.Substring($k, [Math]::Min(60, $text.Length - $k))
            $tm = [regex]::Match($after, '"time":(\d+)')
            $t = 0
            if ($tm.Success) { $t = [long]$tm.Groups[1].Value }
            $decoded = [regex]::Replace($raw, '\\u([0-9a-fA-F]{4})', { param($mm) [char][int]('0x' + $mm.Groups[1].Value) })
            $collect.Add([pscustomobject]@{ Time=$t; Msg=$mid; Type=([regex]::Match($head, '"type":"([a-z]+)"')).Groups[1].Value; Text=$decoded }) | Out-Null
        }
        $i = $i + $typeNeedle.Length
        if ($i -le 0) { $i = $k }
    }
}

$rows = New-Object System.Collections.ArrayList
Get-Parts $text $sidNeedle '","type":"text","text":"' $rows
Get-Parts $text $sidNeedle '","type":"summary","text":"' $rows

$rows = $rows | Sort-Object Time
$sb = New-Object System.Text.StringBuilder
foreach ($r in $rows) {
    $d = if ($r.Time) { ([DateTimeOffset]::FromUnixTimeMilliseconds($r.Time).ToLocalTime().ToString('yyyy-MM-dd HH:mm:ss')) } else { '????-' }
    $who = if ($roleById[$r.Msg]) { $roleById[$r.Msg] } else { '?' }
    [void]$sb.AppendLine("[$d] role=$who type=$($r.Type) msg=$($r.Msg)")
    $clean = ($r.Text -replace '\\n', ' ') -replace '\\r', ' '
    [void]$sb.AppendLine($clean)
    [void]$sb.AppendLine('========================================')
}
$out = $sb.ToString()
[System.IO.File]::WriteAllText("$env:TEMP\opencode\arsheef_full_session.txt", $out, (New-Object System.Text.UTF8Encoding($false)))
"roles found: $($roleById.Count)"
"parts: $($rows.Count)"

