package com.alarsheef.archive.ai

import android.content.Context
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.os.Build
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.io.File

/**
 * OCR على الجهاز نفسه عبر نموذج النظام المدمج
 * (android.graphics.text.TextRecognizer — Android 13+).
 *
 * يُستدعى عبر الانعكاس بدل الاعتماد وقت الترجمة: بعض بيئات SDK المخفّفة
 * لا تُضمّن هذه الفئة في android.jar، لكنها موجودة فعلًا في معظم أجهزة
 * Android 13+ الحقيقية (هي ما يشغّل "تحديد النص الذكي") — الانعكاس يحافظ
 * على ترجمة نجاح دائمًا، ويرجع null بهدوء إذا لم يجد النموذج.
 *
 * الملاحظة: دعم العربية يعتمد على نواة الجهاز؛ إن لم يُرجع نصًّا للغة واحدة
 * يُستخدم النص الموجود على أي حال (أفضل نتيجة ممكنة).
 */
object OcrEngine {

    private const val CLASS_NAME = "android.graphics.text.TextRecognizer"
    private const val MAX_DIMENSION = 2048

    fun isAvailable(context: Context): Boolean {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU) return false
        var instance: Any? = null
        return try {
            val cls = Class.forName(CLASS_NAME)
            instance = cls.getMethod("create", Context::class.java).invoke(null, context) ?: return false
            supportMethods().any { method ->
                runCatching { (cls.getMethod(method).invoke(instance) as? Boolean) ?: false }.getOrDefault(false)
            }
        } catch (e: Throwable) {
            false
        } finally {
            instance?.let { closeInstance(it) }
        }
    }

    suspend fun recognizeFile(context: Context, file: File): String? = withContext(Dispatchers.IO) {
        var instance: Any? = null
        try {
            if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU) return@withContext null
            val cls = Class.forName(CLASS_NAME)
            instance = cls.getMethod("create", Context::class.java).invoke(null, context) ?: return@withContext null
            val supported = supportMethods().any { method ->
                runCatching { (cls.getMethod(method).invoke(instance) as? Boolean) ?: false }.getOrDefault(false)
            }
            if (!supported) return@withContext null

            val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
            BitmapFactory.decodeFile(file.absolutePath, bounds)
            if (bounds.outWidth <= 0 || bounds.outHeight <= 0) return@withContext null

            var sample = 1
            while (maxOf(bounds.outWidth, bounds.outHeight) / sample > MAX_DIMENSION) sample *= 2
            val bitmap = BitmapFactory.decodeFile(
                file.absolutePath,
                BitmapFactory.Options().apply { inSampleSize = sample }
            ) ?: return@withContext null

            try {
                val result = cls.getMethod("recognize", Bitmap::class.java).invoke(instance, bitmap)
                    ?: return@withContext null
                val segmentClass = result.javaClass
                val available = runCatching {
                    (segmentClass.getMethod("isRecognizedTextAvailable").invoke(result) as? Boolean) ?: false
                }.getOrDefault(false)
                if (!available) return@withContext null
                val text = runCatching {
                    (segmentClass.getMethod("getResultText").invoke(result) as? CharSequence)?.toString()
                }.getOrNull()
                val out = text?.trim().orEmpty()
                if (out.length < 3) null else out
            } finally {
                bitmap.recycle()
            }
        } catch (e: Throwable) {
            null
        } finally {
            instance?.let { closeInstance(it) }
        }
    }

    /** TextRecognizer يرث AutoCloseable — نغلقه عبر الانعكاس لتحرير نموذج النص */
    private fun closeInstance(instance: Any) {
        runCatching { instance.javaClass.getMethod("close").invoke(instance) }
    }

    /** "isSupported" أُضيف في API 34؛ الأجهزة على API 33 تعرض isRecognizerSupported */
    private fun supportMethods(): List<String> = listOf("isSupported", "isRecognizerSupported")
}

package com.alarsheef.archive.ai

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import java.io.File
import kotlin.math.abs
import kotlin.math.max
import kotlin.math.min
import kotlin.math.pow
import kotlin.math.sqrt

/** وسم تلقائي: اسم + درجة ثقة 0..1 */
data class ClassifiedLabel(val label: String, val confidence: Float)

/**
 * مصنّف محتوى الصورة يعمل كليًا على الجهاز بدون أي تبعية خارجية.
 * يعتمد على خصائص كلاسيكية مُستخرجة من الصورة (درجة الحدة، التشبّع، السطوع،
 * الهيمنة اللونية، توزع الحواف) وقواعد حاكمة بسيطة تُرجِع وسومًا عربية مثل:
 * "مستند/ورقة" و"لقطة شاشة" و"طبيعة" و"سماء" و"داخلي" و"أبيض وأسود".
 *
 * ليس شبكة عصبية ضخمة — لكنه يغطي التصنيفات الشائعة في أرشيف عائلي
 * بدقة عملية مقبولة مع صفر إنترنت وصفر تنزيلات.
 */
object SmartClassifier {

    private const val ANALYSIS_DIMENSION = 512

    /**
     * يحلل ملف صورة ويعيد الوسوم مرتبة بثقتها (الأعلى أولًا) بدون تكرار.
     * @param facesDetected عدد الوجوه التي اكتشفها ML Kit مسبقًا (إن توفرت) —
     *        تُحول إلى وسم "صورة شخص/وجه" إضافي بثقة ثابتة.
     */
    fun classifyFile(file: File, facesDetected: Int = 0): List<ClassifiedLabel> {
        val bitmap = decodeSampled(file) ?: return emptyList()
        try {
            return classify(bitmap, facesDetected)
        } finally {
            bitmap.recycle()
        }
    }

    fun classify(bitmap: Bitmap, facesDetected: Int = 0): List<ClassifiedLabel> {
        val gray = IntArray(bitmap.width * bitmap.height)
        val sat = FloatArray(bitmap.width * bitmap.height)
        val hue = FloatArray(bitmap.width * bitmap.height)
        var lumSum = 0.0
        var satSum = 0.0
        var minLum = 255.0
        var maxLum = 0.0

        repeat(bitmap.width * bitmap.height) { idx ->
            val x = idx % bitmap.width
            val y = idx / bitmap.width
            val color = bitmap.getPixel(x, y)
            val r = (color shr 16) and 0xFF
            val g = (color shr 8) and 0xFF
            val b = color and 0xFF

            val mx = maxOf(r, g, b)
            val mn = minOf(r, g, b)
            val lum = (0.299 * r + 0.587 * g + 0.114 * b)
            gray[idx] = lum.toInt()
            lumSum += lum
            minLum = min(minLum, lum)
            maxLum = max(maxLum, lum)

            val s = if (mx == 0) 0f else (mx - mn).toFloat() / mx
            sat[idx] = s
            satSum += s

            if (mx != mn) {
                val delta = (mx - mn).toFloat()
                val h = when (mx) {
                    r -> 60f * (((g - b) / delta) % 6f)
                    g -> 60f * (((b - r) / delta) + 2f)
                    else -> 60f * (((r - g) / delta) + 4f)
                }
                hue[idx] = if (h < 0) h + 360f else h
            }
        }

        val w = bitmap.width
        val h = bitmap.height
        val n = gray.size
        val meanLum = lumSum / n
        val meanSat = satSum / n

        // ارتفاعات لونية: سماوي/أزرق (170..260)، أخضر (70..160)، دافئ (0..60 أو 300..360)
        var blueCount = 0
        var greenCount = 0
        var warmCount = 0
        var saturatedCount = 0
        repeat(n) { idx ->
            val hh = hue[idx]
            if (sat[idx] > 0.15f) {
                saturatedCount++
                when {
                    hh in 170f..260f -> blueCount++
                    hh in 70f..160f -> greenCount++
                    hh < 60f || hh >= 300f -> warmCount++
                }
            }
        }
        val blueRatio = blueCount.toFloat() / n
        val greenRatio = greenCount.toFloat() / n
        val warmRatio = warmCount.toFloat() / n

        // درجة انحراف اللون عن الأبيض/الرمادي (تدل على صورة ملونة)
        val chroma = satSum / n

        // كشف الحدود بمشتق بسيط على قناة الإضاءة (Sobel مبسط على الأعمدة بعدد كافٍ)
        var edgeSum = 0.0
        var edgeCount = 0
        var y = 1
        while (y < h - 1 && edgeCount < 40_000) {
            var x = 1
            while (x < w - 1 && edgeCount < 40_000) {
                val gx = gray[y * w + x + 1] - gray[y * w + x - 1]
                val gy = gray[(y + 1) * w + x] - gray[(y - 1) * w + x]
                val mag = sqrt((gx.toDouble() * gx) + (gy.toDouble() * gy))
                edgeSum += mag
                edgeCount++
                x += 2
            }
            y += 2
        }
        val edgeMean = if (edgeCount > 0) edgeSum / edgeCount else 0.0
        // كثافة الحواف القوية (نص/طاولة) — التقطيع وتوزيعها
        var strongRate = 0.0
        if (edgeCount > 0) {
            var strong = 0
            var i = 1
            while (i < w - 1) {
                var j = 1
                while (j < h - 1) {
                    val g = abs(gray[j * w + i + 1] - gray[j * w + i - 1]) +
                        abs(gray[(j + 1) * w + i] - gray[(j - 1) * w + i])
                    if (g > 140) strong++
                    j += 2
                }
                i += 2
            }
            strongRate = strong.toDouble() / (w * h)
        }

        val results = mutableListOf<ClassifiedLabel>()

        // مخطّط روائي/ملف نصي: مستوى رمادي، حواف كثيفة، تباين واسع — تُقوّى كثافة الحواف القوية الرأي
        val docScore = if (meanSat < 0.28 && edgeMean > 14.0 && (maxLum - minLum) > 140) {
            min(0.95f, 0.45f + (edgeMean - 14.0).toFloat() / 80.0f + strongRate.toFloat() * 2.5f)
        } else 0f
        if (docScore >= 0.5f) results += ClassifiedLabel("مستند / ملف نصي", docScore)

        // لقطة شاشة: ألوان مسطّحة، حواف ضعيفة، عدد ألوان مميزة صغير، تباين لوني بسيط
        val screenshotScore = if (edgeMean < 8.0 && meanSat > 0.02f) 0.6f else 0f
        if (screenshotScore > 0f) results += ClassifiedLabel("لقطة شاشة", screenshotScore)

        // طبيعة: نسبة خضرة عالية أو زرقة مع تشبّع جيد
        if (greenRatio > 0.35f || blueRatio > 0.45f) {
            val natureScore = min(0.9f, (max(greenRatio, blueRatio) - 0.3f) * 1.5f + 0.3f)
            when {
                greenRatio > blueRatio -> results += ClassifiedLabel("طبيعة / حديقة", natureScore)
                else -> results += ClassifiedLabel("سماء / ماء", natureScore)
            }
        }

        // داخلي دافئ: ألوان دافئة متفشية وتباين سطوح معتدل
        if (warmRatio > 0.45f && chroma > 0.1f) {
            results += ClassifiedLabel("داخلي / ضوء دافئ", min(0.75f, warmRatio * 1.2f))
        }

        // أبيض وأسود: تشبّع شبه معدوم على كامل الصورة
        if (meanSat < 0.04f) results += ClassifiedLabel("أبيض وأسود / تدرج رمادي", 0.75f)

        // إضاءة منخفضة: سطوع متوسط منخفض جدًا (صور ليلية)
        if (meanLum < 60f) results += ClassifiedLabel("إضاءة منخفضة / ليلية", 0.6f)

        // وجوه — إشارة قوية من ML Kit إن وُجدت
        if (facesDetected > 0) {
            results += ClassifiedLabel(
                if (facesDetected == 1) "صورة شخص / وجه" else "مجموعة أشخاص",
                min(0.9f, 0.55f + facesDetected * 0.12f)
            )
        }

        return results.sortedByDescending { it.confidence }
    }

    /** فك ترميز مصغّر مع فحص الأبعاد أولًا — حماية من نفاد الذاكرة */
    private fun decodeSampled(file: File): Bitmap? {
        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        BitmapFactory.decodeFile(file.absolutePath, bounds)
        if (bounds.outWidth <= 0 || bounds.outHeight <= 0) return null

        var sample = 1
        while (maxOf(bounds.outWidth, bounds.outHeight) / sample > ANALYSIS_DIMENSION) sample *= 2
        return BitmapFactory.decodeFile(
            file.absolutePath,
            BitmapFactory.Options().apply { inSampleSize = sample }
        )
    }
}

package com.alarsheef.archive.ai

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Matrix
import android.graphics.RectF
import android.graphics.PointF
import com.google.mlkit.vision.common.InputImage
import com.google.mlkit.vision.face.Face
import com.google.mlkit.vision.face.FaceLandmark
import com.google.mlkit.vision.face.FaceDetection
import com.google.mlkit.vision.face.FaceDetectorOptions
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlinx.coroutines.withContext
import java.io.File
import kotlin.coroutines.resume

/** نتيجة وجه واحد داخل صورة: مربع الوجه ومواقع العينين إن وجدتا */
data class DetectedFace(
    val box: RectF,
    val leftEye: PointF?,
    val rightEye: PointF?
)

/**
 * تجميع الوجوه على الجهاز بلا إنترنت:
 * 1) اكتشاف الوجوه عبر ML Kit (نموذج مضمّن في التطبيق - متاح في هذا المشروع).
 * 2) قصّ الوجه وتوجيهه أفقياً حسب العينين وتطبيعه 64×64 رمادي.
 * 3) بصمة رقمية dHash (64 بت) تقارن الوجوه بمقياس هامينغ:
 *    مسافة ≤ 10 بت تعني "نفس الشخص" غالبًا.
 *
 * الوصفة بصمتها تقريبية (دقة جيدة تحت إضاءة/زوايا متقاربة) — تُصحَّح يدويًا
 * بدمج/تقسيم المجموعات من الشاشة، وكلها محلية بالكامل.
 */
object FaceGroupingEngine {

    private const val MAX_DETECT_DIMENSION = 1024
    private const val CROP_SIZE = 64
    private const val FACE_PADDING = 0.35f
    /** أقصى مسافة هامينغ للبصمات لاعتبار الوجهين لنفس الشخص */
    const val MATCH_THRESHOLD = 10

    private val options = FaceDetectorOptions.Builder()
        .setPerformanceMode(FaceDetectorOptions.PERFORMANCE_MODE_FAST)
        .setLandmarkMode(FaceDetectorOptions.LANDMARK_MODE_NONE)
        .setClassificationMode(FaceDetectorOptions.CLASSIFICATION_MODE_NONE)
        .build()

    private val detector by lazy { FaceDetection.getClient(options) }

    /** يكتشف الوجوه في ملف صورة (فك ترميز مصغّر حفاظًا على الذاكرة) */
    suspend fun detectFaces(file: File): List<DetectedFace> = withContext(Dispatchers.IO) {
        val bitmap = decodeSampled(file, MAX_DETECT_DIMENSION) ?: return@withContext emptyList()
        try {
            val image = InputImage.fromBitmap(bitmap, 0)
            val faces = suspendCancellableCoroutine<List<Face>> { continuation ->
                detector.process(image)
                    .addOnSuccessListener {
                        if (continuation.isActive) continuation.resume(it)
                    }
                    .addOnFailureListener {
                        if (continuation.isActive) continuation.resume(emptyList())
                    }
            }
            faces.map { face -> toDetectedFace(face, bitmap.width, bitmap.height) }
        } catch (e: Exception) {
            emptyList()
        } finally {
            bitmap.recycle()
        }
    }

    private fun toDetectedFace(face: Face, bitmapW: Int, bitmapH: Int): DetectedFace {
        val box = face.boundingBox
        val left = face.getLandmark(FaceLandmark.LEFT_EYE)?.position
        val right = face.getLandmark(FaceLandmark.RIGHT_EYE)?.position
        return DetectedFace(
            box = RectF(
                box.left.toFloat().coerceIn(0f, bitmapW.toFloat()),
                box.top.toFloat().coerceIn(0f, bitmapH.toFloat()),
                box.right.toFloat().coerceIn(0f, bitmapW.toFloat()),
                box.bottom.toFloat().coerceIn(0f, bitmapH.toFloat())
            ),
            leftEye = left?.let { PointF(it.x, it.y) },
            rightEye = right?.let { PointF(it.x, it.y) }
        )
    }

    /**
     * يقتطع الوجه من الصورة ويوجّهه (حسب محور العينين) ويعيده مقاس 64×64 رمادي.
     * يعيد null لو فشل فك الترميز.
     */
    suspend fun extractCrop(file: File, face: DetectedFace): Bitmap? = withContext(Dispatchers.IO) {
        try {
            val bitmap = decodeSampled(file, MAX_DETECT_DIMENSION) ?: return@withContext null
            try {
                cropFace(bitmap, face)
            } finally {
                bitmap.recycle()
            }
        } catch (e: Exception) {
            null
        }
    }

    private fun cropFace(bitmap: Bitmap, face: DetectedFace): Bitmap? {
        val pad = FACE_PADDING
        val left = (face.box.left - face.box.width() * pad).toInt().coerceAtLeast(0)
        val top = (face.box.top - face.box.height() * pad).toInt().coerceAtLeast(0)
        val right = (face.box.right + face.box.width() * pad).toInt()
            .coerceAtMost(bitmap.width)
        val bottom = (face.box.bottom + face.box.height() * pad).toInt()
            .coerceAtMost(bitmap.height)
        if (right - left < 8 || bottom - top < 8) return null

        var cropped = Bitmap.createBitmap(bitmap, left, top, right - left, bottom - top)

        val eyeL = face.leftEye ?: face.rightEye ?: PointF(face.box.centerX(), face.box.centerY())
        val eyeR = face.rightEye ?: face.leftEye ?: PointF(face.box.centerX(), face.box.centerY())
        val angle = Math.toDegrees(
            Math.atan2((eyeR.y - eyeL.y).toDouble(), (eyeR.x - eyeL.x).toDouble())
        ).toFloat()

        if (angle != 0f) {
            val matrix = Matrix()
            matrix.postRotate(-angle, cropped.width / 2f, cropped.height / 2f)
            val rotated = Bitmap.createBitmap(cropped, 0, 0, cropped.width, cropped.height, matrix, true)
            if (rotated != cropped) cropped.recycle()
            cropped = rotated
        }

        val normalized = Bitmap.createScaledBitmap(cropped, CROP_SIZE, CROP_SIZE, true)
        if (normalized != cropped) cropped.recycle()
        return normalized
    }

    /** بصمة dHash: بعد خفض الدقة إلى 9×8 رمادي بمعدل أخذ أقرب جار → 64 بت */
    fun dHash(bitmap: Bitmap): Long {
        val gray9 = IntArray(9 * 8)
        for (ry in 0 until 8) {
            val sy = (ry * bitmap.height) / 8
            for (rx in 0 until 9) {
                val sx = (rx * bitmap.width) / 9
                val c = bitmap.getPixel(sx.coerceAtMost(bitmap.width - 1), sy.coerceAtMost(bitmap.height - 1))
                val lum = 0.299 * ((c shr 16) and 0xFF) + 0.587 * ((c shr 8) and 0xFF) + 0.114 * (c and 0xFF)
                gray9[ry * 9 + rx] = lum.toInt()
            }
        }
        var hash = 0L
        var bit = 0
        for (ry in 0 until 8) {
            for (rx in 0 until 8) {
                if (gray9[ry * 9 + rx] > gray9[ry * 9 + rx + 1]) {
                    hash = hash or (1L shl bit)
                }
                bit++
            }
        }
        return hash
    }

    fun hammingDistance(a: Long, b: Long): Int = java.lang.Long.bitCount(a xor b)

    fun hashToHex(hash: Long): String = java.lang.Long.toUnsignedString(hash, 16).padStart(16, '0')

    private fun decodeSampled(file: File, maxDim: Int): Bitmap? {
        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        BitmapFactory.decodeFile(file.absolutePath, bounds)
        if (bounds.outWidth <= 0 || bounds.outHeight <= 0) return null
        var sample = 1
        while (maxOf(bounds.outWidth, bounds.outHeight) / sample > maxDim) sample *= 2
        return BitmapFactory.decodeFile(file.absolutePath, BitmapFactory.Options().apply { inSampleSize = sample })
    }
}

package com.alarsheef.archive.dao

import android.content.Context
import androidx.room.Room
import androidx.test.core.app.ApplicationProvider
import androidx.test.ext.junit.runners.AndroidJUnit4
import com.alarsheef.archive.data.AppDatabase
import com.alarsheef.archive.data.dao.ArchivedImageDao
import com.alarsheef.archive.data.entities.ArchivedImage
import com.alarsheef.archive.data.entities.SourceApp
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.runBlocking
import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith

@RunWith(AndroidJUnit4::class)
class ArchivedImageDaoTest {

    private lateinit var db: AppDatabase
    private lateinit var dao: ArchivedImageDao

    @Before
    fun setUp() {
        val context = ApplicationProvider.getApplicationContext<Context>()
        db = Room.inMemoryDatabaseBuilder(context, AppDatabase::class.java)
            .allowMainThreadQueries()
            .build()
        dao = db.archivedImageDao()
    }

    @After
    fun tearDown() {
        db.close()
    }

    private fun image(hash: String, year: Int = 2026, month: Int = 1, day: Int = 1, originalPath: String? = null) =
        ArchivedImage(
            fileName = "IMG_$hash.jpg",
            storedPath = "/data/nonexistent/$hash.jpg",
            contentHash = hash,
            sourceApp = SourceApp.WHATSAPP,
            receivedCount = 1,
            year = year, month = month, day = day,
            importedAt = 0L,
            capturedAt = 0L,
            originalPath = originalPath
        )

    @Test
    fun insert_findByContentHash_roundTrip() = runBlocking {
        val id = dao.insert(image("abc123"))
        val found = dao.findByContentHash("abc123")
        assertNotNull(found)
        assertEquals(id, found!!.id)
        assertEquals("IMG_abc123.jpg", found.fileName)
        assertEquals(SourceApp.WHATSAPP, found.sourceApp)
    }

    @Test
    fun duplicateContentHash_isRejectedByDatabase() = runBlocking {
        dao.insert(image("dup-hash"))
        val second = try {
            dao.insert(image("dup-hash"))
            null
        } catch (e: Exception) {
            e
        }
        // الفهرس الفريد contentHash يجب أن يمنع التكرار على مستوى قاعدة البيانات
        assertTrue(second != null)
        assertEquals(1, dao.getAllOnce().size)
    }

    @Test
    fun findByOriginalPath_returnsOnlyMatchingRow() = runBlocking {
        dao.insert(image("h1", originalPath = "/whatsapp/media/f1.jpg"))
        dao.insert(image("h2", originalPath = "/whatsapp/media/f2.jpg"))
        val found = dao.findByOriginalPath("/whatsapp/media/f2.jpg")
        assertNotNull(found)
        assertEquals("IMG_h2.jpg", found!!.fileName)
        assertNull(dao.findByOriginalPath("/unknown"))
    }

    @Test
    fun incrementReceivedCount_accumulates() = runBlocking {
        val id = dao.insert(image("cnt"))
        dao.incrementReceivedCount(id)
        dao.incrementReceivedCount(id)
        val row = dao.getAllOnce().first()
        assertEquals(3, row.receivedCount)
    }

    @Test
    fun observeYears_groupsByYearDesc() = runBlocking {
        dao.insert(image("a", year = 2026, month = 5, day = 3))
        dao.insert(image("b", year = 2025, month = 12, day = 1))
        dao.insert(image("c", year = 2026, month = 8, day = 2))
        val groups = dao.observeYears().first()
        assertEquals(2, groups.size)
        assertEquals(2026, groups[0].year)
        assertEquals(2, groups[0].fileCount)
        assertEquals(8, groups[0].latestMonth)
        assertEquals(2025, groups[1].year)
    }

    @Test
    fun observeMonthsAndDays_groupCorrectly() = runBlocking {
        dao.insert(image("m1", year = 2026, month = 3, day = 5))
        dao.insert(image("m2", year = 2026, month = 3, day = 9))
        dao.insert(image("m3", year = 2026, month = 7, day = 1))
        val months = dao.observeMonths(2026).first()
        assertEquals(2, months.size)
        assertEquals(7, months[0].month)
        val days = dao.observeDays(2026, 3).first()
        assertEquals(2, days.size)
        assertEquals(9, days[0].day)
        assertEquals(1, days[0].fileCount)
    }

    @Test
    fun searchAll_matchesFileNameSubstring() = runBlocking {
        dao.insert(image("one"))
        dao.insert(image("two"))
        val results = dao.searchAll("IMG_two").first()
        assertEquals(1, results.size)
        assertEquals("IMG_two.jpg", results[0].fileName)
    }

    @Test
    fun deleteDay_removesOnlyThatDay() = runBlocking {
        dao.insert(image("d1", year = 2026, month = 2, day = 1))
        dao.insert(image("d2", year = 2026, month = 2, day = 2))
        dao.deleteDay(2026, 2, 1)
        val remaining = dao.getAllOnce()
        assertEquals(1, remaining.size)
        assertEquals("IMG_d2.jpg", remaining[0].fileName)
    }

    @Test
    fun deleteMonth_removesAllDaysOfMonth() = runBlocking {
        dao.insert(image("e1", year = 2026, month = 4, day = 1))
        dao.insert(image("e2", year = 2026, month = 4, day = 15))
        dao.insert(image("e3", year = 2025, month = 4, day = 15))
        dao.deleteMonth(2026, 4)
        assertEquals(1, dao.getAllOnce().size)
    }

    @Test
    fun deleteYear_removesEverythingOfThatYear() = runBlocking {
        dao.insert(image("f1", year = 2026, month = 1, day = 1))
        dao.insert(image("f2", year = 2025, month = 1, day = 1))
        dao.deleteYear(2026)
        assertEquals(1, dao.getAllOnce().size)
    }

    @Test
    fun moveImage_updatesScopeAndPath() = runBlocking {
        val id = dao.insert(image("g1", year = 2026, month = 1, day = 1))
        dao.moveImage(id, 2027, 6, 15, "/moved/path.jpg")
        val row = dao.getByDayOnce(2027, 6, 15).first()
        assertEquals("/moved/path.jpg", row.storedPath)
        assertTrue(dao.getByDayOnce(2026, 1, 1).isEmpty())
    }
}

