package com.alarsheef.archive.data.dao

import androidx.room.Dao
import androidx.room.Query
import androidx.room.Upsert
import com.alarsheef.archive.data.entities.CustomLabel
import kotlinx.coroutines.flow.Flow

@Dao
interface CustomLabelDao {

    @Upsert
    suspend fun setLabel(label: CustomLabel)

    @Query("DELETE FROM custom_labels WHERE scopeKey = :scopeKey")
    suspend fun clearLabel(scopeKey: String)

    @Query("SELECT * FROM custom_labels")
    fun observeAll(): Flow<List<CustomLabel>>

    @Query("DELETE FROM custom_labels WHERE scopeKey LIKE :prefix || '%'")
    suspend fun clearAllUnderPrefix(prefix: String)
}

package com.alarsheef.archive.data.dao

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import com.alarsheef.archive.data.entities.ArchivedImage
import kotlinx.coroutines.flow.Flow

data class YearSummary(val year: Int, val fileCount: Int, val latestMonth: Int)
data class MonthSummary(val month: Int, val fileCount: Int)
data class DaySummary(val day: Int, val fileCount: Int, val lastImportedAt: Long)

@Dao
interface ArchivedImageDao {

    @Insert(onConflict = OnConflictStrategy.ABORT)
    suspend fun insert(image: ArchivedImage): Long

    @Query("SELECT * FROM archived_images WHERE contentHash = :hash LIMIT 1")
    suspend fun findByContentHash(hash: String): ArchivedImage?

    @Query("SELECT * FROM archived_images WHERE originalPath = :path LIMIT 1")
    suspend fun findByOriginalPath(path: String): ArchivedImage?

    @Query("UPDATE archived_images SET receivedCount = receivedCount + 1 WHERE id = :id")
    suspend fun incrementReceivedCount(id: Long)

    @Query(
        """SELECT year, COUNT(*) as fileCount, MAX(month) as latestMonth
           FROM archived_images GROUP BY year ORDER BY year DESC"""
    )
    fun observeYears(): Flow<List<YearSummary>>

    @Query(
        """SELECT month, COUNT(*) as fileCount FROM archived_images
           WHERE year = :year GROUP BY month ORDER BY month DESC"""
    )
    fun observeMonths(year: Int): Flow<List<MonthSummary>>

    @Query(
        """SELECT day, COUNT(*) as fileCount, MAX(importedAt) as lastImportedAt
           FROM archived_images WHERE year = :year AND month = :month
           GROUP BY day ORDER BY day DESC"""
    )
    fun observeDays(year: Int, month: Int): Flow<List<DaySummary>>

    @Query(
        """SELECT * FROM archived_images WHERE year = :year AND month = :month AND day = :day
           ORDER BY importedAt DESC"""
    )
    fun observeImagesForDay(year: Int, month: Int, day: Int): Flow<List<ArchivedImage>>

    @Query(
        """UPDATE archived_images SET year = :newYear, month = :newMonth, day = :newDay, storedPath = :newPath
           WHERE id = :id"""
    )
    suspend fun moveImage(id: Long, newYear: Int, newMonth: Int, newDay: Int, newPath: String)

    @Query("DELETE FROM archived_images WHERE id IN (:ids)")
    suspend fun deleteByIds(ids: List<Long>)

    @Query(
        """SELECT * FROM archived_images
           WHERE fileName LIKE '%' || :query || '%'
              OR id IN (SELECT imageId FROM ocr_texts WHERE text LIKE '%' || :query || '%')
              OR id IN (SELECT imageId FROM image_labels WHERE label LIKE '%' || :query || '%')
              OR id IN (
                  SELECT imageId FROM face_group_members
                  WHERE groupKey IN (SELECT groupKey FROM face_groups
                                     WHERE name LIKE '%' || :query || '%')
              )
           ORDER BY year DESC, month DESC, day DESC"""
    )
    fun searchAll(query: String): Flow<List<ArchivedImage>>

    @Query("DELETE FROM archived_images WHERE year = :year")
    suspend fun deleteYear(year: Int)

    @Query("DELETE FROM archived_images WHERE year = :year AND month = :month")
    suspend fun deleteMonth(year: Int, month: Int)

    @Query("DELETE FROM archived_images WHERE year = :year AND month = :month AND day = :day")
    suspend fun deleteDay(year: Int, month: Int, day: Int)

    // ---------- حالة التحليل الذكي ----------

    @Query("SELECT * FROM archived_images WHERE aiAnalyzedAt IS NULL ORDER BY id ASC LIMIT :limit")
    suspend fun getPendingAiImages(limit: Int): List<ArchivedImage>

    @Query("SELECT COUNT(*) FROM archived_images WHERE aiAnalyzedAt IS NULL")
    fun observePendingAiCount(): Flow<Int>

    @Query("SELECT COUNT(*) FROM archived_images WHERE aiAnalyzedAt IS NULL")
    suspend fun pendingAiCountOnce(): Int

    @Query("UPDATE archived_images SET aiAnalyzedAt = :time WHERE id = :id")
    suspend fun markAiAnalyzed(id: Long, time: Long)

    @Query("UPDATE archived_images SET aiAnalyzedAt = NULL")
    suspend fun resetAiAnalysis()

    // ---------- قراءات لمرة واحدة (للتصدير/المشاركة بالعناقيد) ----------

    @Query("SELECT * FROM archived_images ORDER BY year DESC, month DESC, day DESC, importedAt DESC")
    suspend fun getAllOnce(): List<ArchivedImage>

    @Query("SELECT * FROM archived_images WHERE year = :year ORDER BY month DESC, day DESC, importedAt DESC")
    suspend fun getByYearOnce(year: Int): List<ArchivedImage>

    @Query("SELECT * FROM archived_images WHERE year = :year AND month = :month ORDER BY day DESC, importedAt DESC")
    suspend fun getByMonthOnce(year: Int, month: Int): List<ArchivedImage>

    @Query("SELECT * FROM archived_images WHERE year = :year AND month = :month AND day = :day ORDER BY importedAt DESC")
    suspend fun getByDayOnce(year: Int, month: Int, day: Int): List<ArchivedImage>
}

package com.alarsheef.archive.data

import android.content.Context
import android.database.Cursor
import android.database.sqlite.SQLiteDatabase
import androidx.room.Room
import androidx.sqlite.db.SupportSQLiteDatabase
import androidx.test.core.app.ApplicationProvider
import androidx.test.ext.junit.runners.AndroidJUnit4
import com.alarsheef.archive.data.AppDatabase.Companion.MIGRATION_1_2
import com.alarsheef.archive.data.AppDatabase.Companion.MIGRATION_2_3
import com.alarsheef.archive.data.AppDatabase.Companion.MIGRATION_3_4
import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith

/**
 * اختبارات الترحيل على ملف SQLite حقيقي (دون الاعتماد على مخططات Room القديمة
 * التي لم تُصدَّر سابقًا): نبني قاعدة بـ user_version القديم يدويًا، ثم نفتحها
 * عبر Room مع سلسلة الترحيلات الكاملة ونتحقق من النتيجة النهائية v4.
 *
 * متطلب التنفيذ: جهاز/محاكّي Android.
 */
@RunWith(AndroidJUnit4::class)
class AppDatabaseMigrationTest {

    private val context: Context = ApplicationProvider.getApplicationContext()
    private val dbName = "migration-test.db"

    @After
    fun tearDown() {
        context.deleteDatabase(dbName)
    }

    // ---------------------------------------------------------------------
    // بناء المخططات القديمة
    // ---------------------------------------------------------------------

    private fun archivedImagesDdl(version: Int): String {
        val columns = StringBuilder(
            "id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, " +
                "fileName TEXT NOT NULL, " +
                "storedPath TEXT NOT NULL, " +
                "contentHash TEXT NOT NULL, " +
                "sourceApp TEXT NOT NULL, " +
                "receivedCount INTEGER NOT NULL, " +
                "year INTEGER NOT NULL, " +
                "month INTEGER NOT NULL, " +
                "day INTEGER NOT NULL, " +
                "importedAt INTEGER NOT NULL, " +
                "capturedAt INTEGER NOT NULL"
        )
        if (version >= 3) columns.append(", originalPath TEXT")
        return "CREATE TABLE archived_images ($columns)"
    }

    private val customLabelsDdl =
        "CREATE TABLE custom_labels (scopeKey TEXT NOT NULL, label TEXT NOT NULL, PRIMARY KEY(scopeKey))"

    /** يُنشئ ملف قاعدة ببنية الإصدار المعطى و user_version الموافق ويُرجع None بعد إغلاقه. */
    private fun createDatabaseAtVersion(version: Int, config: SQLiteDatabase.() -> Unit) {
        context.deleteDatabase(dbName)
        val raw = checkNotNull(
            SQLiteDatabase.openOrCreateDatabase(context.getDatabasePath(dbName), null)
        )
        try {
            raw.execSQL(archivedImagesDdl(version))
            raw.execSQL(customLabelsDdl)
            if (version >= 2) raw.execSQL(
                "CREATE UNIQUE INDEX index_archived_images_contentHash ON archived_images (contentHash)"
            )
            if (version >= 2) raw.execSQL(
                "CREATE INDEX index_archived_images_year_month_day ON archived_images (year, month, day)"
            )
            if (version >= 3) raw.execSQL(
                "CREATE INDEX index_archived_images_originalPath ON archived_images (originalPath)"
            )
            raw.config()
            raw.version = version
        } finally {
            raw.close()
        }
    }

    private fun insertV1V2(raw: SQLiteDatabase, fileName: String, hash: String) {
        raw.execSQL(
            "INSERT INTO archived_images " +
                "(fileName, storedPath, contentHash, sourceApp, receivedCount, year, month, day, importedAt, capturedAt) " +
                "VALUES ('$fileName', '/x/$fileName', '$hash', 'WHATSAPP', 1, 2026, 1, 1, 0, 0)"
        )
    }

    private fun insertV3(raw: SQLiteDatabase, fileName: String, hash: String, originalPath: String?) {
        raw.execSQL(
            "INSERT INTO archived_images " +
                "(fileName, storedPath, contentHash, sourceApp, receivedCount, year, month, day, importedAt, capturedAt, originalPath) " +
                "VALUES ('$fileName', '/x/$fileName', '$hash', 'WHATSAPP', 1, 2026, 1, 1, 0, 0, " +
                (if (originalPath == null) "NULL" else "'$originalPath'") + ")"
        )
    }

    private fun openWithMigrations(): AppDatabase =
        Room.databaseBuilder(context, AppDatabase::class.java, dbName)
            .addMigrations(MIGRATION_1_2, MIGRATION_2_3, MIGRATION_3_4)
            .allowMainThreadQueries()
            .build()

    // ---------------------------------------------------------------------
    // أدوات تحقق
    // ---------------------------------------------------------------------

    private fun rowsCount(db: SupportSQLiteDatabase, table: String): Int =
        db.query("SELECT COUNT(*) FROM $table", null).use { cursor ->
            cursor.moveToFirst() && cursor.getInt(0)
        } ?: 0

    private fun tableColumns(db: SupportSQLiteDatabase, table: String): Set<String> =
        db.query("PRAGMA table_info($table)", null).use { cursor ->
            buildSet {
                while (cursor.moveToNext()) add(cursor.getString(1))
            }
        }

    private fun objectExists(db: SupportSQLiteDatabase, type: String, name: String): Boolean =
        db.query("SELECT COUNT(*) FROM sqlite_master WHERE type = ? AND name = ?", arrayOf(type, name))
            .use { cursor -> cursor.moveToFirst() && cursor.getInt(0) > 0 }

    private fun fileNameForHash(db: SupportSQLiteDatabase, hash: String): String? {
        val projection = "SELECT fileName FROM archived_images WHERE contentHash = '$hash'"
        return db.query(projection, null).use { cursor ->
            if (cursor.moveToFirst()) cursor.getString(0) else null
        }
    }

    // ---------------------------------------------------------------------
    // الاختبارات
    // ---------------------------------------------------------------------

    /** 1→2: إزالة التكرارات (إبقاء أصغر id) وإنشاء الفهارس */
    @Test
    fun migrate1To2_dedupsDuplicatesAndCreatesIndexes() {
        createDatabaseAtVersion(1) {
            insertV1V2(this, "a1.jpg", "dup")
            insertV1V2(this, "a2.jpg", "dup")
            insertV1V2(this, "b1.jpg", "uniq")
        }

        val db = openWithMigrations()
        try {
            val schema = db.openHelper.readableDatabase
            assertEquals(2, rowsCount(schema, "archived_images"))
            assertEquals("a1.jpg", fileNameForHash(schema, "dup"))
            assertTrue(objectExists(schema, "index", "index_archived_images_contentHash"))
            assertTrue(objectExists(schema, "index", "index_archived_images_year_month_day"))

            assertEquals(setOf("a1.jpg", "b1.jpg"), db.archivedImageDao().getAllOnce().map { it.fileName }.toSet())
        } finally {
            db.close()
        }
    }

    /** 2→3: إضافة عمود originalPath مع الحفاظ على البيانات */
    @Test
    fun migrate2To3_addsOriginalPathAndKeepsData() {
        createDatabaseAtVersion(2) {
            insertV1V2(this, "c1.jpg", "hashc")
        }

        val db = openWithMigrations()
        try {
            val schema = db.openHelper.readableDatabase
            assertTrue(tableColumns(schema, "archived_images").contains("originalPath"))
            assertTrue(objectExists(schema, "index", "index_archived_images_originalPath"))
            assertEquals(1, rowsCount(schema, "archived_images"))
            assertEquals("hashc", db.archivedImageDao().getAllOnce().first().contentHash)
        } finally {
            db.close()
        }
    }

    /** 3→4: إضافة aiAnalyzedAt وجداول الذكاء الأربعة دون أي فقدان للبيانات */
    @Test
    fun migrate3To4_addsAiTablesAndPreservesData() {
        createDatabaseAtVersion(3) {
            insertV3(this, "d1.jpg", "hashd1", "/original/d1.jpg")
            insertV3(this, "d2.jpg", "hashd2", null)
            execSQL("INSERT INTO custom_labels (scopeKey, label) VALUES ('y-2026', 'رحلة العائلة')")
        }

        val db = openWithMigrations()
        try {
            val schema = db.openHelper.readableDatabase
            // عمود التحليل الذكي
            assertTrue(tableColumns(schema, "archived_images").contains("aiAnalyzedAt"))
            // الجداول الجديدة
            for (table in listOf("ocr_texts", "image_labels", "face_groups", "face_group_members")) {
                assertTrue("الجدول $table لم يُنشأ", objectExists(schema, "table", table))
            }
            // فهارسها
            assertTrue(objectExists(schema, "index", "index_image_labels_imageId"))
            assertTrue(objectExists(schema, "index", "index_face_group_members_groupKey"))
            // الحفاظ على البيانات
            assertEquals(2, rowsCount(schema, "archived_images"))

            val rows = db.archivedImageDao().getAllOnce()
            assertEquals("/original/d1.jpg", rows.first { it.contentHash == "hashd1" }.originalPath)
            assertNull(rows.first { it.contentHash == "hashd2" }.originalPath)
            assertEquals("رحلة العائلة", db.customLabelDao().observeAll().first { it.scopeKey == "y-2026" }.label)
            assertEquals(1, rowsCount(schema, "custom_labels"))
            // البيانات غير المحلَّلة بعد تبقى null
            assertTrue(rows.all { it.aiAnalyzedAt == null })
        } finally {
            db.close()
        }
    }
}

