param(
    [string]$Action,
    [string]$A1 = "",
    [string]$A2 = "",
    [string]$A3 = "",
    [string]$A4 = ""
)

$adb = "$env:LOCALAPPDATA\Android\Sdk\platform-tools\adb.exe"
$dumpXml = "$env:TEMP\opencode\ui.xml"
$dumpTxt = "$env:TEMP\opencode\ui_dump.txt"

function Run-Adb([string[]]$Args) {
    $out = "$env:TEMP\opencode\adb_out.txt"
    $err = "$env:TEMP\opencode\adb_err.txt"
    $p = Start-Process -FilePath $adb -ArgumentList $Args -Wait -NoNewWindow `
        -RedirectStandardOutput $out -RedirectStandardError $err -PassThru
    return @($p.ExitCode, (Get-Content $out -Raw -ErrorAction SilentlyContinue).Trim(), (Get-Content $err -Raw -ErrorAction SilentlyContinue).Trim())
}

switch ($Action) {
    "dump" {
        $r = Run-Adb @('shell', 'uiautomator', 'dump', '/sdcard/ui_dump.xml')
        if ($r[0] -ne 0) { Write-Output "dump failed: $($r[2])"; exit 1 }
        Run-Adb @('pull', '/sdcard/ui_dump.xml', $dumpXml) | Out-Null
        [xml]$x = Get-Content $dumpXml -Encoding UTF8 -ErrorAction Stop
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($node in $x.SelectNodes('//node')) {
            $text = $node.GetAttribute('text')
            $desc = $node.GetAttribute('content-desc')
            $cls = $node.GetAttribute('class')
            $clickable = $node.GetAttribute('clickable')
            $bounds = $node.GetAttribute('bounds')
            if ($text -eq '' -and $desc -eq '' -and $clickable -ne 'true') { continue }
            $label = if ($text -ne '') { $text } elseif ($desc -ne '') { "[$desc]" } else { "" }
            $coords = ""
            if ($bounds -match '\[(\d+),(\d+)\]\[(\d+),(\d+)\]') {
                $cx = [int](([int]$matches[1] + [int]$matches[3]) / 2)
                $cy = [int](([int]$matches[2] + [int]$matches[4]) / 2)
                $coords = "  @($cx,$cy)"
            }
            $lines.Add("$($cls -replace '^android.widget.','')`t$label  b=$bounds$coords")
        }
        Set-Content -Path $dumpTxt -Value $lines -Encoding UTF8
        Write-Output $lines
    }
    "tap" {
        $r = Run-Adb @('shell', 'input', 'tap', $A1, $A2)
        Write-Output "tap $A1,$A2 exit=$($r[0]) $($r[1])"
    }
    "swipe" {
        $r = Run-Adb @('shell', 'input', 'swipe', $A1, $A2, $A3, $A4, '300')
        Write-Output "swipe exit=$($r[0])"
    }
    "key" {
        $r = Run-Adb @('shell', 'input', 'keyevent', $A1)
        Write-Output "key $A1 exit=$($r[0])"
    }
    "text" {
        $r = Run-Adb @('shell', 'input', 'text', $A1)
        Write-Output "text exit=$($r[0])"
    }
    "am" {
        $r = Run-Adb @('shell', 'am', $A1, $A2, $A3, $A4)
        Write-Output "am exit=$($r[0]) $($r[1])"
    }
    "logcat" {
        $filter = if ($A1) { $A1 } else { 'AndroidRuntime|FATAL|Exception|alarsheef' }
        $r = Run-Adb @('logcat', '-d', '-t', $A2)
        $r[1] -split "`n" | Where-Object { $_ -match $filter -and $_ -notmatch 'ActivityTaskManager|WindowManager|InputDispatcher|Choreographer' } | Select-Object -First 40
    }
    "grant" {
        $r = Run-Adb @('shell', 'appops', 'set', 'com.alarsheef.archive', $A1, $A2)
        Write-Output "appops $A1=$A2 exit=$($r[0]) $($r[1])"
    }
    "screencap" {
        $r = Run-Adb @('shell', 'screencap', '-p', '/sdcard/qa_shot.png')
        Run-Adb @('pull', '/sdcard/qa_shot.png', $A1) | Out-Null
        Write-Output "saved $A1"
    }
    default {
        Write-Output "unknown action: $Action"
        exit 2
    }
}

