    Remove-Item $out, $err -ErrorAction SilentlyContinue
    $p = Start-Process -FilePath $adb -ArgumentList $ArgArray -Wait -NoNewWindow `
        -RedirectStandardOutput $out -RedirectStandardError $err -PassThru
    $stdout = ""; $stderr = ""
    for ($i = 0; $i -lt 30; $i++) {
        try {
