package com.alarsheef.archive.scanner

import android.content.Context
import android.net.Uri
import androidx.documentfile.provider.DocumentFile
import androidx.work.CoroutineWorker
import androidx.work.WorkerParameters
import android.util.Log
import com.alarsheef.archive.data.entities.SourceApp
import com.alarsheef.archive.data.repository.ArchiveRepository
import com.alarsheef.archive.settings.SettingsPreferences
import com.alarsheef.archive.util.FileUtils
import com.alarsheef.archive.util.PermissionUtils
import kotlinx.coroutines.currentCoroutineContext
import kotlinx.coroutines.ensureActive
import kotlinx.coroutines.flow.first
import java.io.File
import java.io.IOException

/**
 * يعمل يوميًا (وعند الطلب اليدوي) لفحص مجلدات واتساب/الاستديو/التنزيلات
 * المفعّلة بالإعدادات إضافةً إلى أي مجلد استيراد مخصص، وأرشفة أي صورة
 * أو PDF جديد.
 *
 * - تتبّع originalPath: أي ملف سبقت أرشفته من نفس المسار يُتجاهل كليًا
 *   دون حساب بصمته ودون زيادة عدّاد الاستلام (يمنع تضخّمه يوميًا).
 * - فحص تدريجي عبر آخر وقت فحص (lastScanAt): الملفات غير المتغيّرة تُتخطى.
 * - معالجة الأخطاء مصنّفة بالنوع لا إعادة محاولة عشوائية.
 * - الملف الأصلي بكل المصادر لا يُحذف أبدًا — النسخ فقط.
 */
class FileScannerWorker(
    context: Context,
    params: WorkerParameters
) : CoroutineWorker(context, params) {

    override suspend fun doWork(): Result {
        val prefs = SettingsPreferences(applicationContext)

        // معطّل في الإعدادات — لا شيء للفحص
        if (!prefs.autoImport.first()) return Result.success()

        // بدون صلاحية الوصول للملفات لا فائدة من الفحص؛ ننهي بهدوء بدل
        // إعادة محاولة عبثية تستنزف البطارية (صلاحية مسحوبة لن تُحل بالتكرار)
        if (!PermissionUtils.hasStorageAccess(applicationContext)) return Result.success()

        return try {
            val repository = ArchiveRepository(applicationContext)
            val startedAt = System.currentTimeMillis()
            val lastScanAt = prefs.lastScanAt.first()

            val sources = buildList {
                if (prefs.sourceWhatsapp.first()) add(SourceApp.WHATSAPP)
                if (prefs.sourceGallery.first()) add(SourceApp.GALLERY)
                if (prefs.sourceDownloads.first()) add(SourceApp.DOWNLOADS)
            }
            val excludePersonalPhotos = prefs.excludePersonalPhotos.first()

            for (source in sources) {
                for (folder in SourceFolders.folders(source)) {
                    if (!folder.exists() || !folder.isDirectory) continue
                    try {
                        scanFolder(folder, source, repository, excludePersonalPhotos, lastScanAt)
                    } catch (e: SecurityException) {
                        // مجلد محمي — لا داعي لإعادة المحاولة عليه
                        Log.w(TAG, "SecurityException أثناء فحص ${folder.absolutePath}: ${e.message}")
                    } catch (e: IOException) {
                        Log.w(TAG, "IOException أثناء فحص ${folder.absolutePath}: ${e.message}")
                        return@doWork Result.retry()
                    }
                }
            }

            // مجلد الاستيراد المخصص (إن حُدّد عبر منتقي النظام)
            val customUri = prefs.importFolderUri.first()
            if (customUri != null) {
                try {
                    scanCustomTree(
                        treeUri = customUri,
                        source = SourceApp.DOWNLOADS,
                        repository = repository,
                        excludePersonalPhotos = excludePersonalPhotos,
                        lastScanAt = lastScanAt
                    )
                } catch (e: SecurityException) {
                    Log.w(TAG, "SecurityException أثناء فحص المجلد المخصص: ${e.message}")
                } catch (e: IOException) {
                    Log.w(TAG, "IOException أثناء فحص المجلد المخصص: ${e.message}")
                    return@doWork Result.retry()
                }
            }

            prefs.setLastScanAt(startedAt)
            // بعد فحص ناجح: نطلق التحليل الذكي للواردات الجديدة على الجهاز
            com.alarsheef.archive.work.AiAnalysisScheduler.start(applicationContext)
            Result.success()
        } catch (e: IOException) {
            Log.w(TAG, "خطأ مؤقت في الفحص: ${e.message}")
            Result.retry()
        } catch (e: SecurityException) {
            // صلاحية سحبت أثناء الفحص — لا معنى لإعادة المحاولة
            Log.w(TAG, "فقدان صلاحية الوصول أثناء الفحص: ${e.message}")
            Result.failure()
        } catch (e: Throwable) {
            // خطأ غير متوقع — نتوقف مع تسجيل واضح بدل حلقة إعادة محاولة لا نهائية
            Log.e(TAG, "خطأ غير متوقع في الفحص", e)
            Result.failure()
        }
    }

    private suspend fun scanFolder(
        folder: File,
        source: SourceApp,
        repository: ArchiveRepository,
        excludePersonalPhotos: Boolean,
        lastScanAt: Long,
        depth: Int = 0
    ) {
        if (depth > MAX_DEPTH) return
        val entries = folder.listFiles() ?: return

        for (entry in entries) {
            currentCoroutineContext().ensureActive()

            if (entry.isDirectory) {
                if (entry.name.startsWith(".")) continue
                scanFolder(entry, source, repository, excludePersonalPhotos, lastScanAt, depth + 1)
                continue
            }
            if (!entry.isFile) continue

            // الملفات غير المتغيّرة منذ آخر فحص تُتخطى
            if (entry.lastModified() <= lastScanAt) continue

            // ملف سبقت أرشفته من نفس المسار؟ نتجاهله كليًا دون إعادة بصمة (القسم 11.3)
            if (repository.findByOriginalPath(entry.absolutePath) != null) continue

            try {
                when {
                    FileUtils.isImage(entry.name) -> {
                        val isPersonalPhoto = excludePersonalPhotos && FaceDetectionUtil.hasFace(entry)
                        if (!isPersonalPhoto) {
                            repository.importFile(
                                sourceFile = entry,
                                sourceApp = source,
                                deleteSourceAfterImport = false,
                                countDuplicate = true,
                                originalPath = entry.absolutePath
                            )
                        }
                    }
                    FileUtils.isPdf(entry.name) -> {
                        val pages = PdfToImageConverter.convertToPngPages(applicationContext, entry)
                        pages.forEach { page ->
                            repository.importFile(
                                sourceFile = page,
                                sourceApp = source,
                                deleteSourceAfterImport = true,
                                countDuplicate = false,
                                originalPath = null
                            )
                            page.delete() // تنظيف الكاش حتى لو فشل الاستيراد
                        }
                    }
                }
            } catch (e: SecurityException) {
                // ملف محمي — نتخطاه ونكمل بالباقي
            } catch (e: IOException) {
                // خطأ قراءة مؤقت — حرفيًا يُعاد عبر إعادة جدولة المهمة بالطبقة الخارجية
                throw e
            }
        }
    }

    /**
     * فحص مجلد الاستيراد المخصص عبر Storage Access Framework (DocumentFile).
     * يُخزَّن معرف الملف المستند (content URI) كـ originalPath لأنه ثابت
     * بين الفحوصات، فتتخطى إعادة معالجة نفس الملفات يوميًا.
     */
    private suspend fun scanCustomTree(
        treeUri: String,
        source: SourceApp,
        repository: ArchiveRepository,
        excludePersonalPhotos: Boolean,
        lastScanAt: Long,
        depth: Int = 0
    ) {
        if (depth > MAX_DEPTH) return
        val root = DocumentFile.fromTreeUri(applicationContext, Uri.parse(treeUri)) ?: return
        visitDocuments(root, source, repository, excludePersonalPhotos, lastScanAt, depth)
    }

    private suspend fun visitDocuments(
        folder: DocumentFile,
        source: SourceApp,
        repository: ArchiveRepository,
        excludePersonalPhotos: Boolean,
        lastScanAt: Long,
        depth: Int
    ) {
        for (doc in folder.listFiles()) {
            currentCoroutineContext().ensureActive()

            if (doc.isDirectory) {
                visitDocuments(doc, source, repository, excludePersonalPhotos, lastScanAt, depth + 1)
                continue
            }
            if (!doc.isFile || doc.name == null) continue

            if (doc.lastModified() <= lastScanAt) continue
            val docIdentity = doc.uri.toString()
            if (repository.findByOriginalPath(docIdentity) != null) continue

            val temp = File(
                applicationContext.cacheDir,
                "custom_${System.nanoTime()}_${doc.name}"
            )
            try {
                applicationContext.contentResolver.openInputStream(doc.uri)?.use { input ->
                    temp.outputStream().use { output -> input.copyTo(output) }
                } ?: continue

                when {
                    FileUtils.isImage(doc.name!!) -> {
                        val isPersonalPhoto = excludePersonalPhotos && FaceDetectionUtil.hasFace(temp)
                        if (!isPersonalPhoto) {
                            repository.importFile(
                                sourceFile = temp,
                                sourceApp = source,
                                deleteSourceAfterImport = true,
                                countDuplicate = true,
                                originalPath = docIdentity
                            )
                        }
                    }
                    FileUtils.isPdf(doc.name!!) -> {
                        val pages = PdfToImageConverter.convertToPngPages(applicationContext, temp)
                        pages.forEach { page ->
                            repository.importFile(
                                sourceFile = page,
                                sourceApp = source,
                                deleteSourceAfterImport = true,
                                countDuplicate = false,
                                originalPath = null
                            )
                            page.delete()
                        }
                    }
                }
            } catch (e: SecurityException) {
                // وثيقة محمية — نتخطاها
            } catch (e: IOException) {
                throw e
            } finally {
                runCatching { temp.delete() }
            }
        }
    }

    companion object {
        const val UNIQUE_WORK_NAME = "daily_archive_scan"
        const val ONE_TIME_WORK_NAME = "manual_archive_scan"
        private const val MAX_DEPTH = 4
        private const val TAG = "FileScannerWorker"
    }
}

